def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row),
             key=lambda c: sum(row.count(c) for row in grid))

    # Extend matching diagonal pairs running from lower-left to upper-right.
    for r in range(h - 1):
        for c in range(1, w):
            color = grid[r][c]
            if color == bg or grid[r + 1][c - 1] != color:
                continue

            # Continue beyond the upper-right and lower-left ends.
            for dr, dc, sr, sc in [(-1, 1, r, c), (1, -1, r + 1, c - 1)]:
                rr, cc = sr + dr, sc + dc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr += dr
                    cc += dc
    return out
